export const BODY: string = "\n<p>تصویروں کو PDF میں بدلنا انہیں بھیجنے، پرنٹ کرنے اور محفوظ کرنے کا سب سے صاف طریقہ ہے۔ PDF ہر آلے پر ایک جیسا نظر آتا ہے، جبکہ تصویریں ہر گیلری میں الگ دکھائی دیتی ہیں۔</p>\n<p>PDF میں کئی تصویریں ایک ہی فائل میں آ جاتی ہیں، جنہیں ترتیب سے دیکھا جا سکتا ہے۔ یہی وجہ ہے کہ اسکول، دفتر اور سرکاری کام میں تصویروں کے بجائے PDF مانگا جاتا ہے۔</p>\n<p>یہ رہنما صفحے کے سائز، سمت، حاشیے، معیار، ترتیب اور پرائیویسی کی وضاحت کرتا ہے۔ تبدیل کرنے کے لیے <a href=\"/ur/tasveer-se-pdf-banayein/\">امیج ٹو PDF</a> کھولیں۔</p>\n<h2 id=\"what-is-image-to-pdf\">امیج ٹو PDF تبدیلی کیا ہے؟</h2>\n<p>امیج ٹو PDF تبدیلی تصویروں کو PDF دستاویز کے صفحات میں بدل دیتی ہے۔ ہر تصویر ایک صفحہ بنتی ہے، اور سب صفحے ایک فائل میں محفوظ ہوتے ہیں۔</p>\n<p>PDF میں تصویریں اپنی جگہ پر رہتی ہیں، اور وصول کرنے والا انہیں اسی ترتیب میں دیکھتا ہے جس میں آپ نے لگائی تھیں۔ کوئی تصویر الگ نہیں کھلتی، سب ایک دستاویز میں رہتی ہیں۔</p>\n<p>یہ تبدیلی براؤزر میں ہوتی ہے، اس لیے تصویریں سرور پر نہیں جاتیں۔ نجی دستاویزات کے لیے یہ بہت اہم ہے۔</p>\n<h2 id=\"why-pdf\">تصویریں بھیجنے کے بجائے PDF کیوں چنیں</h2>\n<p>PDF ہر آلے پر ایک جیسا نظر آتا ہے: فون، کمپیوٹر اور پرنٹر، تینوں پر صفحے کا سائز اور ترتیب وہی رہتی ہے۔ تصویریں ہر ایپ میں الگ سائز میں کھلتی ہیں۔</p>\n<p>PDF میں کئی تصویریں ایک فائل میں بھیجی جا سکتی ہیں، جس سے وصول کرنے والے کو درجنوں فائلیں ڈاؤن لوڈ نہیں کرنی پڑتیں۔ ایک فائل، ایک ڈاؤن لوڈ، سب کچھ ترتیب سے۔</p>\n<p>PDF کو پرنٹ کرنا بھی آسان ہے: ہر تصویر اپنے صفحے پر چھپتی ہے، بغیر سائز بدلنے کے۔ یہی وجہ ہے کہ فارم اور دستاویزات PDF میں مانگے جاتے ہیں۔</p>\n<h2 id=\"page-sizes-explained\">صفحے کے سائز: A4، لیٹر اور تصویر کے مطابق</h2>\n<p>A4 دنیا کا سب سے عام کاغذ ہے، اور لیٹر امریکہ میں استعمال ہوتا ہے۔ دونوں کے ابعاد تھوڑے الگ ہیں، اس لیے فارم کی ہدایت دیکھ کر سائز چنیں۔</p>\n<p>تصویر کے مطابق سائز میں صفحہ تصویر کے ابعاد جیسا بنتا ہے، جس سے کوئی خالی جگہ نہیں بچتی۔ یہ آپشن اس وقت اچھا ہے جب تصویر کو بغیر تراشے پورا دکھانا ہو۔</p>\n<p>غلط سائز چننے سے تصویر چھوٹی یا کٹی ہوئی نکلتی ہے۔ پرنٹ سے پہلے صفحے کا سائز جانچنا ضروری ہے۔</p>\n<h2 id=\"orientation-and-fit\">سمت اور خودکار سمت</h2>\n<p>سمت بتاتی ہے کہ صفحہ سیدھا ہوگا یا چوڑا۔ سیدھی تصویر کے لیے پورٹریٹ اور چوڑی تصویر کے لیے لینڈ اسکیپ چنیں، تاکہ تصویر صفحے کو بھرے۔</p>\n<p>خودکار سمت ہر تصویر کی سمت خود پہچان کر صفحہ بدل دیتی ہے۔ مخلوط تصویروں کے لیے یہ بہترین ہے، کیونکہ ہر صفحہ اپنی تصویر کے مطابق بنتا ہے۔</p>\n<p>اگر سب صفحے ایک ہی سمت میں چاہییں تو خودکار بند کر کے ایک سمت طے کریں۔ اس سے دستاویز یکساں لگتی ہے۔</p>\n<h2 id=\"contain-vs-cover\">کنٹین بمقابلہ کور جگہ</h2>\n<p>کنٹین پوری تصویر کو صفحے میں فٹ کرتا ہے اور خالی جگہ چھوڑ دیتا ہے۔ اس سے کوئی حصہ نہیں کٹتا، مگر صفحے پر سفید حاشیہ رہ جاتا ہے۔</p>\n<p>کور صفحے کو بھرتا ہے اور اضافی حصہ کاٹ دیتا ہے۔ اس سے صفحہ بھرا ہوا لگتا ہے، مگر تصویر کے کنارے کٹ سکتے ہیں۔</p>\n<p>دستاویزات کے لیے کنٹین محفوظ ہے، کیونکہ کچھ کٹتا نہیں۔ پریزنٹیشن کے لیے کور اچھا ہے، کیونکہ صفحہ بھرا ہوا لگتا ہے۔</p>\n<h2 id=\"margins-explained\">حاشیے: کوئی نہیں، چھوٹا اور درمیانہ</h2>\n<p>حاشیہ تصویر اور صفحے کے کنارے کے درمیان جگہ ہے۔ کوئی حاشیہ نہیں کا مطلب ہے تصویر کنارے تک پھیلتی ہے، جو پوسٹر کے لیے اچھا ہے۔</p>\n<p>چھوٹا حاشیہ دستاویز کو صاف ستھرا بناتا ہے، جبکہ درمیانہ حاشیہ پرنٹ کے لیے محفوظ ہے، کیونکہ پرنٹر کنارے تراش سکتا ہے۔</p>\n<p>پرنٹ کرنے والی PDF کے لیے ہمیشہ حاشیہ رکھیں۔ بغیر حاشیے کی تصویر پرنٹ میں کٹ سکتی ہے۔</p>\n<h2 id=\"quality-slider\">PDF تصویر کے معیار کا سلائیڈر</h2>\n<p>معیار کا سلائیڈر طے کرتا ہے کہ PDF میں تصویر کتنی صاف ہوگی۔ زیادہ معیار بڑی PDF بناتا ہے، کم معیار چھوٹی PDF بناتا ہے۔</p>\n<p>پرنٹ کے لیے 90 سے اوپر رکھیں، کیونکہ کاغذ پر ہلکا نقصان بھی نظر آتا ہے۔ ای میل کے لیے 75 سے 85 کافی ہے، جس سے فائل ہلکی رہتی ہے۔</p>\n<p>معیار چننے کے بعد PDF کا سائز دیکھیں۔ اگر وہ ای میل کی حد سے باہر ہو تو معیار تھوڑا کم کریں۔</p>\n<h2 id=\"reordering-pages\">بنانے سے پہلے صفحات کی ترتیب بدلنا</h2>\n<p>تصویریں شامل کرنے کے بعد ان کی ترتیب کھینچ کر بدلی جا سکتی ہے۔ پہلی تصویر پہلا صفحہ بنتی ہے، اس لیے اہم تصویر کو پہلے رکھیں۔</p>\n<p>ترتیب بدلنا آسان ہے، مگر PDF بننے کے بعد بدلنا مشکل ہے۔ اس لیے بنانے سے پہلے ترتیب کو اچھی طرح جانچ لیں۔</p>\n<p>ترتیب میں تاریخ یا نمبر کا خیال رکھیں: پرانے سے نیا، یا پہلے سے آخر تک۔ واضح ترتیب وصول کرنے والے کو دستاویز سمجھنے میں مدد دیتی ہے۔</p>\n<h2 id=\"heic-to-pdf\">HEIC تصویریں سیدھی PDF میں</h2>\n<p>آئی فون کی HEIC تصویریں براہ راست PDF میں بدلی جا سکتی ہیں، بغیر پہلے JPG بنائے۔ ٹول HEIC کو پڑھ کر PDF میں ڈال دیتا ہے۔</p>\n<p>یہ بہت وقت بچاتا ہے، کیونکہ HEIC کو الگ بدلنے کی ضرورت نہیں پڑتی۔ لیکن HEIC کی سمت جانچ لیں، کیونکہ کچھ HEIC تصویریں ترچھی نکلتی ہیں۔</p>\n<p>اگر HEIC تصویر PDF میں نہ کھلے تو اسے پہلے JPG میں بدلیں، پھر PDF بنائیں۔ یہ دو قدم مسئلہ حل کر دیتے ہیں۔</p>\n<h2 id=\"transparency-in-pdf\">PDF کے اندر شفافیت</h2>\n<p>شفاف PNG تصویر PDF میں بھی شفاف رہتی ہے، اور اس کے پیچھے صفحے کا سفید رنگ نظر آتا ہے۔ یہ لوگو اور دستخط کے لیے بہت اہم ہے۔</p>\n<p>اگر شفافیت سفید پس منظر میں بدل جائے تو تصویر کا فارمیٹ جانچیں۔ JPG میں شفافیت نہیں ہوتی، اس لیے شفاف تصویر کو PNG میں رکھیں۔</p>\n<p>پرنٹ میں شفافیت سفید ہی نکلتی ہے، کیونکہ کاغذ شفاف نہیں ہوتا۔ اسکرین پر شفافیت کا فرق نظر آتا ہے، پرنٹ پر نہیں۔</p>\n<h2 id=\"filenames-and-downloads\">فائل کے نام اور PDF ڈاؤن لوڈ کرنا</h2>\n<p>PDF کا نام واضح رکھیں، جیسے دستاویز کی تاریخ یا مقصد۔ واضح نام وصول کرنے والے کو فائل پہچاننے میں مدد دیتا ہے۔</p>\n<p>ڈاؤن لوڈ کرنے کے بعد PDF کھول کر دیکھیں کہ سب صفحے درست ہیں۔ ایک بار بھیجنے کے بعد غلطی درست کرنا مشکل ہوتا ہے۔</p>\n<p>بڑی PDF کو ای میل کرنے سے پہلے اس کا سائز جانچیں۔ اگر وہ حد سے باہر ہو تو معیار کم کریں یا تصویریں کم کریں۔</p>\n<h2 id=\"privacy-and-safety\">پرائیویسی: شناختی کارڈ اور رسیدوں کے لیے محفوظ</h2>\n<p>PDF بنانا آپ کے براؤزر میں ہوتا ہے، تصویریں سرور پر نہیں جاتیں۔ شناختی کارڈ، پاسپورٹ اور بینک رسید جیسی نجی دستاویزات کے لیے یہ بہت اہم ہے۔</p>\n<p>لیکن PDF خود بھی میٹا ڈیٹا رکھ سکتا ہے، اس لیے بھیجنے سے پہلے اسے جانچ لیں۔ نجی معلومات والی PDF کو صرف قابل اعتماد شخص کو بھیجیں۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے، مگر ڈاؤن لوڈ شدہ PDF آپ کے آلے میں رہتی ہے۔ اسے محفوظ جگہ رکھیں۔</p>\n<h2 id=\"pdfs-for-school\">اسکول اور یونیورسٹی کے لیے PDF</h2>\n<p>اسکول میں ہوم ورک، سرٹیفکیٹ اور فارم PDF میں مانگے جاتے ہیں، کیونکہ استاد انہیں ہر آلے پر ایک جیسا دیکھتا ہے۔ تصویروں کے بجائے PDF بھیجنا زیادہ پیشہ ورانہ ہے۔</p>\n<p>اسکول کی PDF میں ہر صفحے پر نام اور تاریخ لکھیں، تاکہ استاد کو معلوم ہو کہ دستاویز کس کی ہے۔ ترتیب بھی واضح رکھیں: پہلے درخواست، پھر ثبوت۔</p>\n<p>اسکول کے فارم کی حد اکثر 2MB ہوتی ہے، اس لیے معیار کو 80 کے آس پاس رکھیں، تاکہ فائل حد کے اندر رہے۔</p>\n<h2 id=\"pdfs-for-work\">کام اور کاروبار کے لیے PDF</h2>\n<p>دفتر میں رسیدیں، معاہدے اور رپورٹیں PDF میں بھیجی جاتی ہیں، کیونکہ PDF کو بدلا نہیں جا سکتا۔ وصول کرنے والا وہی دیکھتا ہے جو آپ نے بھیجا تھا۔</p>\n<p>کاروباری PDF میں کمپنی کا لوگو پہلے صفحے پر لگائیں اور صفحات کو نمبر دیں۔ یہ دستاویز کو پیشہ ورانہ اور قابل اعتماد بناتا ہے۔</p>\n<p>کاروباری PDF کو ای میل کرنے سے پہلے اس کا سائز جانچیں، کیونکہ بڑی فائل اسپیم فلٹر میں پھنس سکتی ہے۔</p>\n<h2 id=\"scanning-tips\">صاف PDF کے لیے اسکین کرنے کی تجاویز</h2>\n<p>اسکین کرتے وقت کاغذ کو سیدھا رکھیں اور اچھی روشنی میں تصویر لیں۔ ترچھی یا سایہ والی تصویر PDF میں خراب لگتی ہے۔</p>\n<p>اسکین کی تصویر کو PDF بنانے سے پہلے کراپ کریں، تاکہ میز یا ہاتھ نظر نہ آئے۔ صاف کنارے دستاویز کو پیشہ ورانہ بناتے ہیں۔</p>\n<p>اسکین کے لیے 300 ڈی پی آئی کافی ہے۔ اس سے زیادہ ریزولوشن فائل بڑی کر دیتا ہے، بغیر کوئی فائدہ دیے۔</p>\n<h2 id=\"sharing-and-storing-pdfs\">تیار شدہ PDF شیئر کرنا اور محفوظ کرنا</h2>\n<p>PDF کو کلاؤڈ میں محفوظ کریں، تاکہ وہ ہر آلے سے مل سکے۔ فائل کا نام تاریخ اور مقصد سے رکھیں، تاکہ بعد میں تلاش کرنا آسان ہو۔</p>\n<p>PDF شیئر کرتے وقت لنک کی بجائے فائل بھیجیں، اگر وصول کرنے والے کو آف لائن دیکھنا ہو۔ لنک انٹرنیٹ مانگتا ہے، فائل نہیں۔</p>\n<p>اہم PDF کی ایک نقل الگ جگہ بھی رکھیں، تاکہ ایک نقل کھو جانے پر دوسری کام آئے۔</p>\n<h2 id=\"pdfs-for-travel\">سفر کے دستاویزات کے لیے PDF</h2>\n<p>سفر میں پاسپورٹ، ٹکٹ اور ہوٹل کی بکنگ کی PDF اپنے فون میں رکھیں، تاکہ انٹرنیٹ نہ ہونے پر بھی وہ مل سکیں۔ ایک PDF میں سب دستاویزات رکھنا سب سے آسان ہے۔</p>\n<p>سفر کی PDF کو آف لائن دستیاب رکھیں اور اس کی ایک نقل ای میل میں بھی بھیج دیں۔ فون کھو جانے پر ای میل سے دستاویزات واپس مل سکتی ہیں۔</p>\n<p>سفر کی PDF میں ذاتی معلومات ہوتی ہیں، اس لیے اسے عوامی وائی فائی پر نہ کھولیں اور فون کو لاک رکھیں۔ JPG اور PNG کے فرق کے لیے <a href=\"/ur/blog/jpg-se-pdf-vs-png-se-pdf/\">JPG بمقابلہ PNG PDF</a> اور عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-ko-pdf-mein-kaise-convert-karein/\">تصویر کو PDF میں کیسے بدلیں</a> پڑھیں۔ HEIC بدلنی ہو تو <a href=\"/ur/heic-ko-jpg-mein-convert-karein/\">HEIC ٹو JPG</a> دیکھیں۔</p>\n";

